contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount, uint extra) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount) + (extra)); require(amount <= 1000000000000000000000000000000); require(extra <= 1000000000000000000000000000000);
        require(address(this).balance >= amount + extra);
        require(amount + extra > 0);

        uint balBefore = address(c).balance;

        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;
        c.deposit{value: extra}(); if (__ESBMC_reverted()) return;

        c.withdrawAll(); if (__ESBMC_reverted()) return;

        uint balAfter = address(c).balance;

        assert(balAfter == balBefore);
    }
}

