// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount, uint256 extra) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        extra = bound(extra, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP + VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount + extra);
        vm.assume(amount + extra > 0);
        uint balBefore = address(c).balance;
        try c.deposit{value: amount}() {} catch { return; }
        try c.deposit{value: extra}() {} catch { return; }
        try c.withdrawAll() {} catch { return; }
        uint balAfter = address(c).balance;
        assertTrue(balAfter == balBefore);
    }

    function testFuzz_run(uint256 amount, uint256 extra) public {
        _run(amount, extra);
    }

    receive() external payable {}
}
